        if any(not data.Bars.ContainsKey(self.symbols[ticker])
               for ticker in self.tickers):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self._update_market_state(spy_close, aapl_close)
            return

        current_spy_sma = self.spy_sma.Current.Value
        current_rsi = self.aapl_rsi.Current.Value

        if self.IsWarmingUp:
            self._update_market_state(
                spy_close, aapl_close, current_spy_sma
            )
            return

        spy_crossed_below = (
            self.previous_spy_sma is not None
            and self.previous_close.get(self.spy) is not None
            and self.previous_close[self.spy] <= self.previous_spy_sma
            and spy_close > current_spy_sma
        )

        spy_crossed_above = (
            self.previous_spy_sma is not None
            and self.previous_close.get(self.spy) is not None
            and self.previous_close[self.spy] >= self.previous_spy_sma
            and spy_close < current_spy_sma
        )

        aapl_red_for_three = self.aapl_red_streak >= 3
        aapl_rsi_above_60 = current_rsi > 60

        if self.strategy_a_lot > 0 and spy_crossed_above:
            self.MarketOrder(
                self.spy, -self.strategy_a_lot, tag="Strategy A sell"
            )
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and aapl_rsi_above_60:
            self.MarketOrder(
                self.aapl, -self.strategy_b_lot, tag="Strategy B sell"
            )
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crossed_below:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )
            if quantity > 0:
                self.MarketOrder(
                    self.spy, quantity, tag="Strategy A buy"
                )
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and aapl_red_for_three:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl, quantity, tag="Strategy B buy"
                    )
                    self.strategy_b_lot = quantity

        self._update_market_state(
            spy_close, aapl_close, current_spy_sma
        )

    def _update_market_state(self, spy_close, aapl_close, spy_sma=None):
        previous_aapl_close = self.previous_close.get(self.aapl)

        if previous_aapl_close is not None:
